{
  "identity": {
    "name": "Ardent Industries Inc.",
    "location": "1020 N. Franklin Blvd Suite 101 Nampa, ID 83687",
    "claims": [
      {
        "statement": "The business name is Ardent Industries Inc.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "© 2026 Ardent Industries Inc. All rights reserved."
      },
      {
        "statement": "The company's street address is 1020 N. Franklin Blvd Suite 101 Nampa, ID 83687.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "1020 N. Franklin Blvd Suite 101 Nampa, ID 83687"
      },
      {
        "statement": "The company was established in California in 2014 and relocated to Idaho in 2017.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/about-us/",
        "quote": "Ardent Industries was established in California in 2014, relocating to Idaho in 2017."
      },
      {
        "statement": "The company states it is locally owned and operated.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "As a locally owned and operated business, we understand the needs of the Treasure Valley community"
      }
    ]
  },
  "industry": {
    "industry": "Metal Fabrication and Manufacturing",
    "activities": [
      "Precision sheet metal fabrication (laser cutting, press brake, hardware)",
      "CNC machining (milling and turning)",
      "Powder coating",
      "MIG and TIG welding"
    ],
    "claims": [
      {
        "statement": "Ardent Industries specializes in precision sheet metal fabrication, CNC machining, powder coating, and welding services.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "We specialize in precision sheet metal fabrication, CNC machining, powder coating, and welding services in Nampa, Idaho, and the surrounding Treasure Valley."
      },
      {
        "statement": "The company manufactures components for industries including semiconductor, robotics, chemical processing, home furnishings, electronic components, and automotive aftermarket.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "including but not limited to semiconductor, robotics, chemical processing, home furnishings, electronic components, and automotive aftermarket."
      },
      {
        "statement": "Ardent Industries operates as a B2B and custom metal manufacturing shop rather than a residential HVAC, plumbing, or electrical home-service contractor.",
        "label": "inference",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://ardentindustries.net/",
    "claims": [
      {
        "statement": "The official website presents pages for About Us, Machining, Powder Coating, Sheet Metal, Welding, Media, Store, and Contact Us.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "ABOUT US MACHINING POWDER COATING SHEET METAL WELDING MEDIA STORE CONTACT US"
      },
      {
        "statement": "The website lists a business phone number of [redacted] and an email address of [redacted].",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "[redacted] [redacted]"
      },
      {
        "statement": "The company serves the Treasure Valley region and ships manufactured products to clients in other states.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/about-us/",
        "quote": "We have the experience to facilitate packaging and logistics to ensure your products arrive undamaged to whatever corner of the country you’re in."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The website footer identifies the business as an incorporated entity, Ardent Industries Inc.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "© 2026 Ardent Industries Inc. All rights reserved."
      }
    ],
    "limitations": "No contractor license numbers, state registration numbers, or industry certification numbers are displayed on the inspected public pages."
  },
  "existingSoftware": [
    {
      "product": "WordPress with Astra theme and Elementor Pro",
      "purpose": "Website content management and page building",
      "evidence": {
        "statement": "The homepage loads scripts from wp-includes and wp-content paths for themes/astra and plugins/elementor-pro.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "https://ardentindustries.net/wp-content/plugins/elementor-pro/assets/js/frontend.min.js?ver=3.6.5"
      }
    },
    {
      "product": "WooCommerce",
      "purpose": "Online store and cart functionality",
      "evidence": {
        "statement": "The homepage loads scripts from the woocommerce plugin directory.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "https://ardentindustries.net/wp-content/plugins/woocommerce/assets/js/frontend/woocommerce.min.js?ver=11.1.2"
      }
    },
    {
      "product": "Facebook for WooCommerce",
      "purpose": "Ad pixel tracking and e-commerce event attribution",
      "evidence": {
        "statement": "The homepage loads scripts from the facebook-for-woocommerce plugin directory.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "https://ardentindustries.net/wp-content/plugins/facebook-for-woocommerce/assets/js/frontend/pixel-events.js?ver=3.7.6"
      }
    },
    {
      "product": "Google Tag Manager (gtag.js)",
      "purpose": "Website analytics and tag management",
      "evidence": {
        "statement": "The homepage loads a gtag.js script from googletagmanager.com.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "https://www.googletagmanager.com/gtag/js?id=G-S7Z5B0C32M"
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The Contact Us page uses a basic web form collecting name, phone number, email, and message for manufacturing inquiries.",
      "label": "fact",
      "sourceUrl": "https://ardentindustries.net/contact-us/",
      "quote": "Your Name Your Phone Number Your Email Your Message"
    },
    {
      "statement": "The company states it uses standard operating procedures and advanced machinery and software to manufacture parts.",
      "label": "fact",
      "sourceUrl": "https://ardentindustries.net/",
      "quote": "We use advanced machinery and software to manufacture parts that fit perfectly to your specifications."
    }
  ],
  "problems": [
    {
      "problem": "Custom manufacturing RFQ intake via a general contact form or email may require manual engineering review and quoting.",
      "label": "hypothesis",
      "basis": "The Contact Us page only asks for name, phone, email, and free-text message without structured CAD file upload or automated quoting fields, though actual internal quoting workflows are not visible."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Dedicated manufacturing ERP / job-shop quoting software",
      "addresses": "Managing custom fabrication RFQs, CAD files, bill of materials, and shop floor scheduling",
      "alreadyOwned": false
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended because the company is outside ForgeX's target segment of residential HVAC, plumbing, and electrical contractors."
  },
