    "sourcesUsed": [
      {
        "url": "https://ardentindustries.net/",
        "usedFor": "Business identity, location, core manufacturing activities, existing website software stack, and contact information."
      },
      {
        "url": "https://ardentindustries.net/about-us/",
        "usedFor": "Company history, founding year, relocation to Idaho, and geographic service scope."
      },
      {
        "url": "https://ardentindustries.net/contact-us/",
        "usedFor": "Contact form structure and verification of contact details."
      }
    ],
    "limitations": [
      "Employee headcount is not stated on the inspected pages.",
      "Names of owners, executives, or managers are not stated on the inspected pages.",
      "Internal ERP, CAD/CAM, and accounting systems cannot be verified from the public website.",
      "No licensing or registration numbers are published on the inspected pages."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "Ardent Industries Inc. is a precision sheet metal fabrication, CNC machining, powder coating, and welding manufacturer serving industrial and commercial markets. It is outside ForgeX's segment of owner-led residential HVAC, plumbing, and electrical home-service contractors."
  }
